'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => v == null ? '—' : new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v);
const num = (v,d=2) => v == null ? '—' : Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
const pct = v => v == null ? '—' : `${v>0?'+':''}${num(v)}%`;
const date = v => v ? new Date(v).toLocaleString('zh-CN',{timeZone:'America/New_York',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})+' ET' : '—';
const family = {EARNINGS_REVISION:'业绩拐点',GUIDANCE_CHANGE:'指引调整',CAPITAL_RETURN:'资本回报',INSIDER_OPEN_MARKET_BUY:'内部人买入',ACTIVIST_OWNERSHIP:'主动股东',MATERIAL_CORPORATE_EVENT:'重大公司事件',FINANCING_DILUTION:'融资 / 摊薄',MNA_SPECIAL:'并购 / 特殊情形'};
const states = {WATCH:'观察中',READY:'条件已满足',INVALIDATED:'逻辑已失效',MANAGE:'持仓管理',ENTERED:'已记录入场',EXITED:'已退出',IGNORED:'已忽略',VERIFIED:'已验证事件',DISCOVERED:'待验证',QUALIFIED:'已达门槛'};
const reaction = {BALANCED_REACTION:'正常候选区间',EXTENDED_REACTION:'反应已过度',ADVERSE_REACTION:'反向反应 · 需复核',CAUTION:'需更强确认',PENDING:'市场窗口待补齐'};
const roles = {ENTRY_CANDIDATE:'入场候选',POSITION_RISK:'持仓风险',CONTEXT_ONLY:'背景信息'};
const material = {HIGH:'高重要性',VERY_HIGH:'极高重要性',MEDIUM:'中等重要性',LOW:'低重要性',MATERIAL_RISK:'重大风险'};
const titles = {research:'研究动态',today:'今日概览',opportunities:'机会研究',watchlist:'观察列表',portfolio:'投资组合',evidence:'证据中心',history:'历史与复盘',settings:'设置与数据源',detail:'机会详情'};
const reasons = {EVIDENCE_OFFICIAL_CONFIRMED:'证据链已确认',EVIDENCE_MISSING:'官方证据缺失',DATA_COMPLETE:'关键数据完整',DATA_STALE:'市场数据过期',DATA_BROKER_STALE:'组合快照过期',REACTION_EXTENDED:'市场反应已经过度',REACTION_ADVERSE:'价格出现反向反应',TRIGGER_READY:'入场条件已满足',TRIGGER_NOT_READY:'等待进一步确认',INVALID_TIME_EXPIRED:'等待窗口已超时',INVALID_PRICE:'价格失效条件已触发',RISK_BUYING_POWER:'现金或购买力不足',RISK_SECTOR_CONCENTRATION:'板块集中度过高',RISK_POSITION_CONCENTRATION:'单票集中度过高',RISK_PLANNED_LOSS:'计划亏损超过硬上限',RISK_BROKER_RECONCILIATION:'组合尚未完成对账'};
let syncBusy=false, syncFinished=null;
let csrf='', status={}, opportunities=[], currentPage='', detail=null, modalData=null, filterState='', filterFamily='', filterSearch='', watchTab='ALL', renderEpoch=0;
const api = async (path,body,key,retry=true) => {
  const response = await fetch('/api/v1'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...(key?{'Idempotency-Key':key}:{})},body:JSON.stringify(body)});
  if(retry && [401,403].includes(response.status) && path!=='/session'){csrf=(await api('/session')).csrf_token;return api(path,body,key,false);}
  const data=await response.json();
  if(!response.ok) throw new Error(data.error || `请求失败 (${response.status})`);
  return data;
};
const key=()=>crypto.randomUUID();
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500);}
const badge = state => `<span class="badge ${esc(state)}">${esc(state)}${states[state]?' · '+states[state]:''}</span>`;
const heading = (eyebrow,title,subtitle,actions='') => `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const exportLink = (scope,format,label,params='')=>`<a class="button ${format==='json'?'ghost':''}" href="/api/v1/${scope}/export?format=${format}${params}" download>↓ ${label}</a>`;
const empty = (title='暂时没有符合条件的机会',text='没有机会，也是有效结论。系统不会为凑数量而降低证据与风控门槛。')=>`<div class="empty"><div>◇</div><h3>${title}</h3><p>${text}</p></div>`;
const section = (title,body,extra='')=>`<section class="detail-panel"><h2>${title}${extra}</h2>${body}</section>`;
function bestCalculation(c){return c.calculations.find(x=>x.change!==undefined)||c.calculations.find(x=>x.new!==undefined)||null;}
function changeText(c){const x=bestCalculation(c);if(!x)return material[c.materiality]||c.materiality;return x.change!==undefined ? `${x.change>0?'+':''}${num(x.change)}${x.unit}` : `${num(x.new)}${x.unit==='%'?'%':x.unit==='USD'?' USD':''}`;}
function changeLabel(c){const labels={revenue_guidance:'收入指引中值变化',eps_guidance:'EPS 指引中值变化',gross_margin_guidance:'毛利率指引变化',operating_margin:'营业利润率变化',buyback_to_market_cap:'回购授权 / 市值',potential_dilution:'潜在摊薄比例',insider_cluster:'合资格内部人买入',deal_spread:'协议报价价差'};return labels[bestCalculation(c)?.metric]||'事件重要性';}
function nextTrigger(c){if(c.state==='INVALIDATED')return reasons[c.invalidation_status[0]]||c.invalidation_status[0];if(c.trigger_status==='READY')return '所有预定义条件已通过，等待用户复核';return c.entry_conditions.find(x=>!x.pass)?.label || '等待新证据';}
function card(c,index=0){return `<article class="opportunity-card"><div class="card-top"><div class="ticker-icon tone-${index%3}">${esc(c.ticker.slice(0,1))}</div><div><a class="ticker" href="#detail/${esc(c.opportunity_id)}">${esc(c.ticker)}</a><div class="company-name">${esc(c.issuer_name)}</div></div><div class="card-type">${badge(c.state)}<small>${family[c.event_family]} · ${date(c.event_at)}</small></div></div><h3 class="card-title">${esc(c.catalyst)}</h3><p class="card-summary">${esc(material[c.materiality])}变化 · ${esc(reaction[c.reaction.bucket])} · ${esc(roles[c.role])}</p><div class="card-metrics"><div class="metric"><small>${changeLabel(c)}</small><strong>${changeText(c)}</strong></div><div class="metric"><small>相对板块反应</small><strong>${pct(c.reaction.sector_excess_pct)}</strong></div><div class="metric"><small>相对成交量</small><strong>${num(c.reaction.relative_volume)}<span>×</span></strong></div></div><div class="card-footer"><span class="dot"></span><span class="trigger">${esc(nextTrigger(c))}</span><a href="#detail/${esc(c.opportunity_id)}">查看研究 ↗</a></div></article>`;}
function table(items,action=true){if(!items.length)return empty();return `<div class="table-panel"><table><thead><tr><th>标的 / 公司</th><th>事件类型</th><th>变化幅度</th><th>板块超额反应</th><th>状态</th>${action?'<th></th>':''}</tr></thead><tbody>${items.map(c=>`<tr><td><a href="#detail/${esc(c.opportunity_id)}"><strong>${esc(c.ticker)}</strong><small>${esc(c.issuer_name)}</small></a></td><td>${family[c.event_family]}<small>${roles[c.role]}</small></td><td>${changeText(c)}</td><td>${pct(c.reaction.sector_excess_pct)}</td><td>${badge(c.state)}</td>${action?`<td><a class="button ghost" href="#detail/${esc(c.opportunity_id)}">查看 ↗</a></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function stat(label,value,note,icon,emphasis=false){return `<div class="stat ${emphasis?'emphasis':''}"><div class="stat-label"><span>${label}</span><span>${icon}</span></div><div class="stat-number">${value}</div><small>${note}</small></div>`;}
function today(){const ready=opportunities.filter(c=>c.state==='READY'),watch=opportunities.filter(c=>c.state==='WATCH'),invalid=opportunities.filter(c=>c.state==='INVALIDATED'),attention=opportunities.filter(c=>c.role==='POSITION_RISK'),filtered=opportunities.filter(c=>['VERIFIED','DISCOVERED','IGNORED'].includes(c.state));const cards=[...ready,...watch].slice(0,3);
return heading('YOUR DAILY RESEARCH BRIEF','让重要变化，浮出水面。','从公司事实出发，寻找值得等待的机会。每一个结论，都有据可循。',`<button class="button ghost" data-action="refresh-all">↻ 刷新评估</button>${exportLink('today','markdown','导出今日研究')}`)+`<div class="stats-grid">${stat('待观察机会',watch.length,'已通过证据与重要性门槛','◇')}${stat('条件已满足',ready.length,'仍需用户确认，才可记录入场','↗',true)}${stat('持仓风险事件',attention.length,'事件提示，请结合实际持仓复核','◉')}${stat('已失效机会',invalid.length,'保留原始逻辑与完整记录','◷')}</div><div class="two-columns"><div><div class="section-title"><h2>值得关注的变化 <small>FOCUS LIST</small></h2><a class="text-link" href="#opportunities">全部事件 ${opportunities.length} →</a></div><div class="opportunity-list">${cards.length?cards.map(card).join(''):empty()}</div></div><aside class="aside-grid"><section class="side-panel"><div class="panel-head">从事件，到机会 <span>DETERMINISTIC</span></div><div class="funnel"><span>已归档事件</span><b>${opportunities.length}</b></div><div class="funnel"><span>待复核 / 仅背景 / 已忽略</span><b>${filtered.length}</b></div><div class="funnel"><span>观察中</span><b>${watch.length}</b></div><div class="funnel"><span>条件已满足</span><b>${ready.length}</b></div><div class="pipeline-bottom">系统允许 0 个机会。事件重要，并不代表已经具备入场条件。</div></section><section class="side-panel"><div class="panel-head">工作区状态 <a href="#settings">↗</a></div><div class="readiness-ring">${status.mode==='demo'?'DEMO':'LOCAL'}</div><div class="release-copy"><strong>${status.mode==='demo'?'固定时点模拟回放':'真实数据 · 只读研究'}</strong><br>生产发布门禁未通过<br>真实交易已关闭</div><div class="divider"></div><div class="source-row"><span class="dot"></span> SEC EDGAR<i>${status.mode==='demo'?'演示数据隔离':sourceLabel('sec')}</i></div><div class="source-row"><span class="dot"></span> Massive<i>${status.mode==='demo'?'合成市场快照':sourceLabel('massive')}</i></div><div class="source-row"><span class="dot"></span> IBKR<i>只读 / 待验证</i></div></section><section class="side-panel insight-panel"><div class="quote">“</div><p>好消息 ≠ 好的入场时机。<br>先理解变化，再观察市场已经反应了多少。</p><small>RESEARCH PRINCIPLE / 01</small></section></aside></div><section class="bottom-section"><div class="section-title"><h2>风险与背景事件 <small>CONTEXT, NOT SIGNALS</small></h2><a class="text-link" href="#evidence">查看原始证据 →</a></div>${table(opportunities.filter(c=>c.role!=='ENTRY_CANDIDATE'))}</section>`;
}
function sourceLabel(id){return {NOT_CONFIGURED:'尚未连接',HEALTHY:'已连接',DEGRADED:'连接降级'}[status.sources?.find(s=>s.id===id)?.state]||'尚未连接';}
function filteredItems(base){return base.filter(c=>(!filterState||c.state===filterState)&&(!filterFamily||c.event_family===filterFamily)&&(!filterSearch||[c.ticker,c.issuer_name].join(' ').toLowerCase().includes(filterSearch.toLowerCase())));}
function filters(){return `<div class="filters"><input class="input search" id="filter-search" type="search" placeholder="搜索代码或公司名称…" aria-label="搜索代码或公司" value="${esc(filterSearch)}"><select id="filter-state" aria-label="按状态筛选"><option value="">所有状态</option>${Object.keys(states).map(k=>`<option value="${k}" ${filterState===k?'selected':''}>${k} · ${states[k]}</option>`).join('')}</select><select id="filter-family" aria-label="按事件类型筛选"><option value="">所有事件类型</option>${Object.entries(family).map(([k,v])=>`<option value="${k}" ${filterFamily===k?'selected':''}>${v}</option>`).join('')}</select><button class="button ghost" data-action="reset-filter">重置</button></div>`;}
function opportunitiesPage(){return heading('OPPORTUNITY RESEARCH','机会研究','重要事件与可执行机会分开呈现。使用筛选器检查每一条决策依据。',exportLink('opportunities','csv','导出筛选结果',`${filterState?'&state='+filterState:''}${filterFamily?'&family='+filterFamily:''}${filterSearch?'&q='+encodeURIComponent(filterSearch):''}`))+filters()+`<div id="filtered-table">${table(filteredItems(opportunities))}</div>`;}
function watchlist(){const base=opportunities.filter(c=>['WATCH','READY','INVALIDATED'].includes(c.state));const items=base.filter(c=>watchTab==='ALL'||c.state===watchTab);return heading('PERSONAL WATCHLIST','观察列表','耐心等待条件成立；如果逻辑被破坏，及时记录失效。',exportLink('watchlist','json','导出观察列表'))+`<div class="tabs">${[['ALL','全部'],['WATCH','观察中'],['READY','条件已满足'],['INVALIDATED','已失效']].map(([k,label])=>`<button data-watch-tab="${k}" class="${watchTab===k?'active':''}">${label} <span class="count-pill">${base.filter(c=>k==='ALL'||c.state===k).length}</span></button>`).join('')}</div>${table(items)}`;}
function detailPage(c){const sizing=c.portfolio.sizing;const rawEvidence=c.evidence.map(e=>`<div class="evidence-block"><header><span class="badge">${c.is_demo?'DEMO · 合成原文':esc(e.level)}</span><strong>${esc(e.source_id)}</strong><span class="row-end">${esc(e.locator)}</span></header><p>${esc(e.excerpt)}</p><code>SHA-256 ${esc(e.sha256)}</code><div class="actions spaced"><a href="/api/v1/evidence/${esc(e.raw_document_id)}/raw" target="_blank" rel="noopener">查看已归档原文 ↗</a>${!c.is_demo&&/^https:\/\/(www\.)?sec\.gov\//.test(e.url)?`<a href="${esc(e.url)}" target="_blank" rel="noopener">SEC 官方来源 ↗</a>`:''}</div></div>`).join('');
return `<a class="detail-back" href="#opportunities">← 返回机会研究</a>`+heading('EVIDENCE-LED OPPORTUNITY',`<div class="detail-top"><div class="ticker-icon">${esc(c.ticker[0])}</div><span>${esc(c.ticker)}</span>${badge(c.state)}</div>`,`${esc(c.issuer_name)} · ${family[c.event_family]} · ${date(c.event_at)}`,`${exportLink('opportunities/'+c.opportunity_id,'json','JSON')}${exportLink('opportunities/'+c.opportunity_id,'markdown','导出研究')}`)+`<div class="detail-grid"><div>${section('发生了什么',`<p>${esc(c.catalyst)}</p><div class="detail-metrics">${stat(changeLabel(c),changeText(c),material[c.materiality],'')}${stat('板块超额反应',pct(c.reaction.sector_excess_pct),reaction[c.reaction.bucket],'')}${stat('相对成交量',num(c.reaction.relative_volume)+'×',c.reaction.vwap_relation==='ABOVE'?'当前价格高于事件 VWAP':'当前价格未站上 VWAP','')}</div><div class="notice ${c.trigger_status==='READY'?'success':''}">${esc(nextTrigger(c))}。${c.role!=='ENTRY_CANDIDATE'?'此事件仅作'+roles[c.role]+'，不会产生入场 READY。':'工作流状态不代表买入建议。'}</div><dl class="key-values"><div><dt>事件角色</dt><dd>${roles[c.role]}</dd></div><div><dt>事件会话</dt><dd>${esc(c.session.session)}</dd></div><div><dt>原始价格反应 / 相对 SPY</dt><dd>${pct(c.reaction.raw_return_pct)} / ${pct(c.reaction.spy_excess_pct)}</dd></div><div><dt>板块本身回报</dt><dd>${pct(c.reaction.sector_return_pct)}</dd></div><div><dt>等待确认窗口</dt><dd>${esc(c.holding_window)}</dd></div></dl>`)}${section('可复算的基本面变化',c.calculations.length?`<div class="table-panel"><table class="facts-table"><thead><tr><th>指标</th><th>原值 → 新值</th><th>变化</th></tr></thead><tbody>${c.calculations.map(x=>`<tr><td><strong>${esc(x.metric)}</strong><small>${esc(x.formula)}</small></td><td>${num(x.old)} → ${num(x.new)}</td><td>${x.change==null?'—':num(x.change)} ${esc(x.unit)}</td></tr>`).join('')}</tbody></table></div>`:empty('尚无可量化的变化','该事件需要按照具体经济机制复核，不填充推测数值。'))}${section('证据链与标准化事实',rawEvidence+`<div class="table-panel"><table class="facts-table"><thead><tr><th>事实 / 版本</th><th>值 / 单位</th><th>期间 / 证据</th></tr></thead><tbody>${c.facts.map(f=>`<tr><td><strong>${esc(f.metric_id)}</strong><small>v${esc(f.fact_version)}</small></td><td>${esc(f.value)}<small>${esc(f.unit)}</small></td><td>${esc(f.period_start)} → ${esc(f.period_end)}<small>${esc(f.evidence_id)} · ${esc(f.locator||'')}</small></td></tr>`).join('')}</tbody></table></div>`)}${section('历史类比',`<div class="notice">可用样本 n = ${c.historical_context.n} · ${esc(c.historical_context.status)}</div><p>${c.historical_context.n<10?'样本少于 10，仅保留可追溯个案，不展示胜率或分布结论。':'仅为历史描述性统计，不构成未来收益预测。'}</p>${c.historical_context.statistics?`<pre class="hash">${esc(JSON.stringify(c.historical_context.statistics,null,2))}</pre>`:''}`)}${section('状态流转记录',`<ol class="timeline">${c.transitions.map(t=>`<li>${esc(t.from_state)} → <strong>${esc(t.to_state)}</strong><small>${date(t.created_at)} · ${esc(t.actor)} · ${esc(t.reason_code)}</small></li>`).join('')}</ol><button class="button" data-action="replay" data-id="${esc(c.opportunity_id)}">↻ 验证确定性重放</button>`)}${status.mode!=='demo'?section('行情更新',`<button class="button" data-action="market-sync" data-id="${esc(c.opportunity_id)}">同步 Massive 并重新计算</button>`):''}${section('稳定原因码',`<div class="code-list">${c.reason_codes.map(r=>`<code title="${esc(reasons[r]||r)}">${esc(r)}</code>`).join('')}</div><p class="hash">Rule ${esc(c.rule_version)}<br>Snapshot ${esc(c.data_snapshot_version)}<br>Core ${esc(c.core_output_hash)}</p>`)}</div><aside class="detail-aside"><div>${section('入场条件',`<ul class="check-list">${c.entry_conditions.map(x=>`<li><span class="check-icon ${x.pass?'pass':''}">${x.pass?'✓':'·'}</span><span>${esc(x.label)}</span></li>`).join('')}</ul><div class="divider"></div><div class="actions"><button class="button primary full-width" data-action="enter" ${c.state!=='READY'||c.trigger_status!=='READY'||status.mode!=='demo'?'disabled':''}>复核纸面入场计划 →</button>${['WATCH','READY'].includes(c.state)?`<button class="button" data-action="watch" data-id="${esc(c.opportunity_id)}">保持观察</button><button class="button ghost" data-action="ignore" data-id="${esc(c.opportunity_id)}">忽略</button>`:''}</div><p class="label-note">只在隔离演示工作区模拟成交。真实账户订单接口关闭。</p>`)}${section('失效条件',`<dl class="key-values"><div><dt>价格参考线</dt><dd>${money(c.invalidation_rules.price)}</dd></div><div><dt>已等待 / 上限</dt><dd>${c.invalidation_rules.elapsed_trading_sessions??'—'} / ${c.invalidation_rules.expiry_trading_sessions} 个交易日</dd></div></dl><p>${esc(c.invalidation_rules.basis)}</p><p>${esc(c.invalidation_rules.fundamental)}</p>${c.invalidation_status[0]!=='NONE'?`<div class="notice">${c.invalidation_status.map(r=>esc(reasons[r]||r)).join('<br>')}</div>`:''}`)}</div><div>${section('组合与仓位工作表',sizing?`<dl class="key-values"><div><dt>拟入场价</dt><dd>${money(sizing.entry)}</dd></div><div><dt>每股计划风险</dt><dd>${money(sizing.per_share_risk)}</dd></div><div><dt>默认风险预算</dt><dd>${money(sizing.risk_budget)}</dd></div><div><dt>最多股数</dt><dd>${num(sizing.max_shares,0)}</dd></div><div><dt>计划占用资金</dt><dd>${money(sizing.planned_capital)}</dd></div><div><dt>计划最大亏损</dt><dd>${money(sizing.planned_loss)}</dd></div></dl><p>按风险预算、集中度、现金和未平仓风险中最严格的限制计算。</p>${c.risk_flags.length?`<div class="notice">${c.risk_flags.map(x=>esc(reasons[x]||x)).join('<br>')}</div>`:'<div class="notice success">当前快照下，未触及组合硬限制。</div>'}`:empty('组合数据待补齐','没有有效快照，不提供可执行仓位。'))}${section('研究说明',`<button class="button" data-action="ai-explain" data-id="${esc(c.opportunity_id)}">DeepSeek 解释此机会</button><p>核心事实、计算、状态和导出均独立于 AI。${status.ai_mode==='assist'?'DeepSeek 辅助解释独立于核心规则，点击下方按钮生成。':'AI 当前已关闭。'}</p><p class="label-note">${c.is_demo?'此案例全部数值均为合成数据，仅供功能验收。':'请核实证据时间、行情授权和组合快照。'}</p>`)}</div></aside></div>`;
}
function portfolioPage(data){const p=data.snapshot;const positions=p.positions||[];const openRisk=positions.reduce((s,x)=>s+(x.planned_loss||0),0),exposure=positions.reduce((s,x)=>s+(x.market_value||0),0);return heading('PORTFOLIO & THESIS','投资组合','持续跟踪原始逻辑、风险预算与集中度。系统不会自动买入或卖出。',exportLink('portfolio','json','导出组合'))+`<div class="stats-grid">${stat('账户权益',money(p.equity),'本地纸面快照 / 已对账数据','▥')}${stat('可用现金',money(p.cash),'不使用推算的未知购买力','◇')}${stat('股票敞口',p.equity?pct(exposure/p.equity*100):'—','按当前快照估值','◫')}${stat('未平仓计划风险',p.equity&&positions.every(x=>x.planned_loss!=null)?pct(openRisk/p.equity*100):'—','预警 3% · 硬上限 5%','◎')}</div><div class="section-title"><h2>持仓与原始 Thesis</h2><small class="muted">快照 ${date(p.captured_at)}</small></div>${positions.length?`<div class="table-panel"><table><thead><tr><th>标的 / 板块</th><th>数量</th><th>资金占用</th><th>计划亏损</th><th>原始逻辑</th><th></th></tr></thead><tbody>${positions.map(x=>`<tr><td><strong>${esc(x.ticker)}</strong><small>${esc(x.sector)}</small></td><td>${num(x.quantity)}</td><td>${money(x.market_value)}</td><td>${money(x.planned_loss)}</td><td class="wrap">${esc(x.thesis?.thesis||(status.mode==='demo'?'演示组合背景持仓，无关联事件。':x.event_family||'持仓逻辑待补齐'))}</td><td>${x.position_id?`<button class="button" data-action="exit" data-id="${esc(x.position_id)}" data-entry="${esc(x.entry_price)}">记录退出</button>`:'<span class="muted">只读快照</span>'}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无持仓','先连接只读账户并完成证券映射和对账；演示模式可通过二次确认记录纸面入场。')}<section class="bottom-section"><div class="section-title"><h2>需要复核的事件</h2></div>${table(data.attention)}</section>`;}
function evidencePage(queue){return heading('SOURCE OF TRUTH','证据中心','保留原始文档、哈希、引用位置及事实版本。AI 解释不属于官方证据。',exportLink('events','csv','导出事件'))+`<div class="stats-grid">${stat('已归档事件',opportunities.length,'与证券和原始文件关联','▤')}${stat('事实记录',opportunities.reduce((s,c)=>s+c.facts.length,0),'每个事实具有证据定位','◇')}${stat('待复核文档',queue.length,'未经验证不会成为交易结论','◷')}${stat('审计链',status.audit?.valid?'完整':'异常','追加存储，历史计算不可覆盖','✓',true)}</div>${queue.length?section('待复核队列',queue.map(r=>`<div class="review-card"><span class="badge">${esc(r.status)}</span><div><strong>${esc(r.data?.accession||r.id)}</strong><br>${esc(r.reason)}<br><small>${date(r.created_at)}</small>${r.filing_id&&status.mode!=='demo'?`<br><button class="button" data-action="ai-extract" data-id="${esc(r.filing_id)}">DeepSeek 提取候选事实</button><button class="button" data-action="sec-exhibits" data-id="${esc(r.filing_id)}">补齐 EX-99 展品</button>`:''}${r.data?.primary_document_id?`<br><a href="/api/v1/evidence/${esc(r.data.primary_document_id)}/raw" target="_blank" rel="noopener">已归档原文 ↗</a>`:''}</div></div>`).join('')):''}<div class="section-title"><h2>事件证据与事实链</h2></div>${table(opportunities)}<div class="notice">${status.mode==='demo'?'演示工作区的 E1 结构只是测试证据层级，不代表真实 SEC 披露。所有模拟公司均以 .D 标记。':'已归档披露进入待复核队列。只有证据定位、数字对账和市场窗口均通过后，才能参与核心规则计算。'}</div>`;}
function historyPage(data){const closed=data.outcomes.filter(x=>x.phase==='EXIT');return heading('OUTCOMES & LEARNING','历史与复盘','保留决策当时的证据、规则和计划；区分执行结果与策略结论。',`${exportLink('outcomes','csv','导出结果')}${exportLink('performance','csv','事件族表现')}`)+`<div class="stats-grid">${stat('已完成交易',closed.length,'30 笔起进行初步复核','◷')}${stat('已实现净损益',money(closed.reduce((s,x)=>s+x.net_pnl,0)),'已扣除记录的手续费','◇')}${stat('不可变结果记录',data.outcomes.length,'入场和退出分别追加','▤')}${stat('结论等级',closed.length<30?'样本不足':'初步复核','单事件族 100 笔后正式复核','◎')}</div><div class="section-title"><h2>已退出 / 已失效 / 已忽略</h2></div>${table(data.items)}<section class="bottom-section"><div class="section-title"><h2>交易结果账本</h2></div>${closed.length?`<div class="table-panel"><table><thead><tr><th>标的</th><th>入场 / 退出</th><th>净损益</th><th>R 倍数</th><th>退出原因</th><th>MFE / MAE</th></tr></thead><tbody>${closed.map(x=>`<tr><td><strong>${esc(x.ticker)}</strong></td><td>${money(x.entry_price)} / ${money(x.exit_price)}</td><td>${money(x.net_pnl)}</td><td>${num(x.r_multiple)}R</td><td>${esc(x.exit_reason)}</td><td>${x.mfe==null?'未采集价格路径':pct(x.mfe)} / ${x.mae==null?'—':pct(x.mae)}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无已完成交易','纸面入场会保存原始 Thesis；退出确认后生成不可变结果记录。')}</section><section class="bottom-section"><div class="section-title"><h2>事件族复核</h2></div><div class="table-panel"><table><thead><tr><th>事件族</th><th>样本数</th><th>净损益</th><th>平均 R</th><th>复核等级</th></tr></thead><tbody>${data.family_performance.map(x=>`<tr><td>${family[x.event_family]}</td><td>${x.n}</td><td>${money(x.net_pnl)}</td><td>${num(x.mean_r)}</td><td>${esc(x.review_level)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function settingsPage(securities,integrations){return heading('SYSTEM & DATA SOURCES','设置与数据源','核心决策来自版本化规则。接入外部服务前，请在本机配置凭证。')+`<div class="settings-grid"><div class="full">${section('API 对接与计算验收',`<dl class="key-values"><div><dt>Massive REST / WebSocket</dt><dd>适配器已实现 · ${integrations.massive.configured?'已配置，待账户实测':'待配置 API Key'}</dd></div><div><dt>IBKR 组合 / 订单 / 成交</dt><dd>适配器已实现 · ${integrations.ibkr.configured?'已配置，待 Gateway 实测':'待配置账户'}</dd></div><div><dt>交易日历依赖</dt><dd>${integrations.dependencies.exchange_calendars?'已安装':'需使用 .venv 启动'}</dd></div><div><dt>无账户自检</dt><dd>${integrations.last_offline_check?integrations.last_offline_check.passed?'通过 · 合成样例':'未通过':'尚未运行'}</dd></div></dl><div class="actions spaced"><button class="button primary" data-action="integration-check">运行无账户自检</button><button class="button" data-action="market-calculate" ${status.mode==='demo'?'disabled':''}>计算事件行情</button><button class="button" data-action="broker-map" ${status.mode==='demo'?'disabled':''}>映射 IBKR 证券</button><button class="button" data-action="broker-plan" ${status.mode==='demo'?'disabled':''}>记录持仓失效计划</button><button class="button" data-action="broker-orders">券商订单与成交记录</button></div><p>自检不访问外部 API。覆盖对齐行情、VWAP、量比、超额收益、组合风险、部分成交和重复回报。账户连通性、行情权限及券商纸面验收需配置后验证。</p>`)}</div>${section('AI 辅助模式',`<div class="setting-row"><div><strong>核心能力始终可用</strong><p>开关仅影响可选解释，不影响机会状态和仓位。</p></div><div class="mode-switch"><button data-ai="off" class="${status.ai_mode==='off'?'active':''}">AI Off</button><button data-ai="assist" class="${status.ai_mode==='assist'?'active':''}">AI Assist</button></div></div><div class="notice ${status.ai_mode==='off'?'success':''}">${status.ai_mode==='off'?'AI 已关闭。导出、规则计算、风险与纸面流程全部可用。':(status.ai_provider?.configured?'DeepSeek 已配置。候选提取和研究解释需主动触发或开启自动提取。':'DeepSeek 待配置：在本机 .env 添加 DEEPSEEK_API_KEY，核心工作流不受影响。')}</div>`)}${section('版本与运行环境',`<dl class="key-values"><div><dt>产品版本</dt><dd>1.0.2</dd></div><div><dt>规则版本</dt><dd>${esc(status.rule_version)}</dd></div><div><dt>工作区</dt><dd>${status.mode==='demo'?'隔离的模拟数据回放':'Shadow / 只读数据'}</dd></div><div><dt>真实订单提交</dt><dd>关闭</dd></div><div><dt>审计记录</dt><dd>${status.audit.count} 条 · ${status.audit.valid?'哈希链完整':'需要复核'}</dd></div></dl>`)}<div class="full">${section('数据源连接',`<div class="table-panel"><table><thead><tr><th>数据源</th><th>职责</th><th>状态</th><th>最近成功</th><th>授权</th><th></th></tr></thead><tbody>${status.sources.filter(x=>x.id!=='demo').map(s=>`<tr><td><strong>${esc(s.id.toUpperCase())}</strong></td><td>${{sec:'官方披露与 XBRL',massive:'历史 / 实时市场数据',ibkr:'只读组合与持仓'}[s.id]}</td><td>${sourceLabel(s.id)}${s.last_error?`<small>${esc(s.last_error)}</small>`:''}</td><td>${date(s.last_success)}</td><td>待核验数据许可</td><td>${s.id==='ibkr'?'<button class="button" data-action="ibkr-sync">同步只读账户</button>':s.id==='massive'?'<button class="button" data-action="market-fetch">拉取历史行情</button>':'<a class="text-link" href="#registry">选择证券后同步 ↓</a>'}</td></tr>`).join('')}</tbody></table></div><p>凭证保存在本机 .env，界面不会读取或显示密钥。SEC 需要合规 User-Agent；IBKR 需要已登录的本地 TLS Gateway。历史行情不会被静默当作实时行情。</p>`)}</div><div class="full" id="registry">${section('证券注册与 SEC 披露同步',`<form id="security-form"><div class="form-grid"><label class="form-field">交易代码<input class="input" name="ticker" placeholder="例如 MSFT" pattern="[A-Za-z0-9.\-]{1,16}" required></label><label class="form-field">SEC CIK（10 位）<input class="input" name="cik" placeholder="例如 0000789019" pattern="[0-9]{10}" required></label><label class="form-field">公司名称<input class="input" name="name" placeholder="公司法定名称" required maxlength="100"></label><label class="form-field">板块<input class="input" name="sector" placeholder="Technology" required maxlength="60"></label></div><div class="actions spaced"><button class="button primary" type="submit">注册到个人 Watchlist</button><span class="label-note">SEC 同步时会再次核验 ticker / CIK 映射。</span></div></form><div class="divider"></div>${securities.length?`<div class="table-panel"><table><thead><tr><th>证券</th><th>CIK</th><th>公司</th><th></th></tr></thead><tbody>${securities.map(s=>`<tr><td><strong>${esc(s.ticker)}</strong></td><td>${esc(s.cik)}</td><td>${esc(s.issuer_name)}</td><td><button class="button" data-action="sec-sync" data-id="${esc(s.id)}" ${status.mode==='demo'?'disabled':''}>同步最近披露</button></td></tr>`).join('')}</tbody></table></div>`:empty('尚未注册证券','注册后可抓取 SEC 官方披露。S&P 500 / Nasdaq 100 成分需按历史生效日期导入，不猜测成分。')}`)}</div>${section('经过验证的数据包导入',`<p>支持导入包含 event 和 market_snapshot 的 JSON。系统验证证据归属、数字原文、单位、期间和数据环境；不接受未经核实的 AI 事实。</p><label class="form-field">选择 JSON 数据包<input type="file" id="import-file" accept="application/json,.json" class="input"></label><div class="actions spaced"><button class="button" data-action="import">验证并导入</button></div><p>真实数据必须引用已通过 SEC 同步归档的原始文档。模拟与真实数据保存在不同数据库中。</p>`)}${section('生产发布门禁',`<span class="badge INVALIDATED">PRODUCTION_BLOCKED</span><ul class="check-list">${status.blockers.map(x=>`<li><span class="check-icon">·</span>${esc(x)}</li>`).join('')}</ul>`)}<div class="full">${section('审计与运行指标',`<div class="actions"><button class="button" data-action="audit">查看审计记录</button><a class="button" href="/metrics" target="_blank" rel="noopener">Prometheus 指标 ↗</a></div><p>数据源失败显式记录 DEGRADED。原始证据、事实、计算和结果采用不可变追加存储。</p>`)}</div></div>`;}
async function loadData(){[status,{items:opportunities}]=await Promise.all([api('/status'),api('/opportunities')]);$('#workspace-mode').textContent=status.mode==='demo'?'DEMO / 合成数据回放':'SHADOW / 只读研究';$('#ai-indicator').textContent=status.ai_mode==='off'?'AI OFF':(status.ai_provider?.configured?'DEEPSEEK · AI ASSIST':'DEEPSEEK · 待配置');$('#clock-label').textContent=date(status.as_of);$('#ready-count').textContent=opportunities.filter(x=>x.state==='READY').length;$('#environment-banner').innerHTML=status.mode==='demo'?`<strong>DEMO MODE</strong><span>合成数据演示 · 虚构公司与价格 · 回放时点 ${date(status.as_of)}</span><a href="#settings">查看运行边界 ↗</a>`:`<strong>SHADOW MODE</strong><span>真实数据只读研究 · 所有生产发布门禁通过前，真实交易保持关闭</span><a href="#settings">数据源与发布状态 ↗</a>`;}

const researchLabels={RESEARCH_READY:'研究条件满足',RESEARCH_WATCH:'继续观察',NEEDS_REVIEW:'证据待核对',INVALIDATED:'逻辑已失效',CONTEXT:'背景 / 风险信息'};
function researchDetailsPage(data){return heading('RESEARCH ACTIVITY','研究动态','查看最近披露、待核对事实与判断记录。完成复核后，在机会研究中持续跟踪。',`<button class="button primary" data-action="research-run" ${status.mode==='demo'?'disabled':''}>更新研究数据</button><a class="button" href="#settings">配置数据源</a>`)+`<div class="stats-grid">${stat('已归档披露',(data.disclosures||[]).length,'展示最近归档记录，按披露时间排序','▤')}${stat('事实待复核',data.drafts.filter(x=>x.status==='REVIEW_REQUIRED').length,'先核对原文，再跟踪判断','◇')}${stat('未读提醒',data.notices.filter(x=>!x.read_at).length,'更新与研究事项','◎')}${stat('已保存判断',(data.impact_history||[]).length,'最近判断快照，供追踪依据变化','◷')}</div><div class="actions spaced"><a class="button" href="#today">查看今日概览</a><a class="button" href="#opportunities">进入机会研究 →</a></div><details class="detail-panel"><summary>最近判断记录（${(data.impact_history||[]).length}）</summary>${impactHistory(data)}</details>${data.last_run?`<p class="label-note">最近更新 ${date(data.last_run.finished_at)} · ${esc(data.last_run.state)} · ${esc((data.last_run.errors||[]).join(' / '))}</p>`:''}<details class="detail-panel"><summary>个人关注设置与自动提取</summary>${section('个人关注设置',`<form id="research-preferences"><p>关注证券（取消勾选可暂停该证券的个人研究更新）</p><div class="actions">${data.securities.map(s=>`<label><input type="checkbox" name="security_ids" value="${esc(s.id)}" ${data.preferences.security_ids==null||data.preferences.security_ids.includes(s.id)?'checked':''}> ${esc(s.ticker)}</label>`).join('')||'请先在设置页注册股票。'}</div><p>关注事件</p><div class="actions">${Object.entries(family).map(([k,v])=>`<label><input type="checkbox" name="families" value="${esc(k)}" ${data.preferences.families.includes(k)?'checked':''}> ${esc(v)}</label>`).join('')}</div><p><label><input type="checkbox" name="watchlist_only" ${data.preferences.watchlist_only?'checked':''}> 只研究已注册且生效的关注证券</label></p><p><label><input type="checkbox" name="auto_extract" ${data.preferences.auto_extract?'checked':''}> 更新时自动调用 DeepSeek 提取新披露（开启 AI Assist 且配置 Key 后生效，每轮最多 5 份）</label></p><button class="button" type="submit">保存研究偏好</button> <a class="text-link" href="#settings">添加关注股票 →</a></form>`)}</details>${section('候选事实复核',data.drafts.length?data.drafts.map(d=>`<div class="review-card"><span class="badge">${esc(d.status)}</span><div><strong>${esc(d.ticker)} · ${esc(d.candidate?.catalyst||'候选披露')}</strong><p>${date(d.event_at)}${Date.now()-Date.parse(d.event_at)>30*86400000?' · 历史披露，请勿作为当前机会':''} · AI 候选，待核对原文 · ${esc(d.assessment?.bucket?('初步重要性：'+(material[d.assessment.bucket]||d.assessment.bucket)):'证据不足，暂不判断')}</p><details><summary>查看提取数值与校验结果</summary>${(d.calculations||[]).map(c=>`<p>${esc(c.metric)}：${num(c.change??c.new)} ${esc(c.unit)} · ${esc(c.formula)}</p>`).join('')}<p>${esc((d.validation_errors||[]).join('；')||'数字与引用检查通过，仍需人工核对指标含义和期间。')}</p></details><button class="button" data-action="review-draft" data-id="${esc(d.id)}" ${d.status==='APPROVED'?'disabled':''}>核对原文并编辑事实</button></div></div>`).join(''):empty('暂无候选事实','自动提取完成后显示在这里。暂无候选不等于没有机会，请同时检查同步状态、AI 额度和数据覆盖。'))}${section('最新真实披露',(data.disclosures||[]).length?data.disclosures.map(f=>`<div class="review-card"><div><strong>${esc(f.ticker)} · ${esc(f.form)}</strong><p>${date(f.accepted_at)} · 已归档原文，不代表已确认机会</p><a class="text-link" href="/api/v1/evidence/${esc(f.raw_document_id)}/raw" target="_blank" rel="noopener">查看 SEC 原文 ↗</a></div></div>`).join(''):empty('暂无披露','正在等待首次同步；请查看页面顶部的数据状态。'))}${section('研究提醒',data.notices.length?data.notices.map(n=>`<div class="review-card"><div><strong>${esc(n.data.message)}</strong><small>${date(n.created_at)}</small></div>${!n.read_at?`<button class="button" data-action="notice-read" data-id="${esc(n.id)}">标记已读</button>`:'<span class="muted">已读</span>'}</div>`).join(''):empty('暂无提醒','新候选、研究条件满足或更新失败会记录在这里。提醒保存在本机，不发送邮件。'))}`;}

async function render(){const epoch=++renderEpoch;const [page,id]=(location.hash.slice(1)||'today').split('/');currentPage=titles[page]?page:'today';$('#page-label').textContent=titles[currentPage];$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===currentPage));let html;try{if(currentPage==='today')html=status.mode==='demo'?today():researchPage(await api('/research'),true);else if(currentPage==='research')html=researchDetailsPage(await api('/research'));else if(currentPage==='opportunities')html=status.mode==='demo'?opportunitiesPage():researchPage(await api('/research'));else if(currentPage==='watchlist')html=watchlist();else if(currentPage==='detail'){detail=await api('/opportunities/'+encodeURIComponent(id));html=detailPage(detail);}else if(currentPage==='portfolio')html=portfolioPage(await api('/portfolio'));else if(currentPage==='history')html=historyPage(await api('/history'));else if(currentPage==='evidence')html=evidencePage(await api('/review-queue'));else if(currentPage==='settings'){const [securities,integrations]=await Promise.all([api('/securities'),api('/integrations')]);html=settingsPage(securities,integrations);}if(epoch===renderEpoch){$('#main').innerHTML=html;window.scrollTo({top:0,behavior:'instant'});if(currentPage==='opportunities'&&id?.startsWith('impact-'))document.getElementById(decodeURIComponent(id))?.scrollIntoView({block:'start'});}}catch(e){if(epoch===renderEpoch)$('#main').innerHTML=`<div class="error-panel">${esc(e.message)}<div class="actions spaced"><button class="button" data-action="reload">重试</button></div></div>`;}}
async function reload(){await loadData();await render();}
function openModal(title,body,footer=''){const modal=$('#modal');$('#modal-content').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="关闭对话框">×</button></div><div class="modal-body">${body}<div class="form-error" id="modal-error" role="alert"></div></div><div class="modal-footer">${footer}</div>`;if(!modal.open)modal.showModal();}
function entryModal(){const c=detail,s=c.portfolio.sizing;modalData={opportunity:c,createKey:key()};openModal('1 / 2 · 制定纸面入场计划',`<p>${esc(c.ticker)} · ${esc(c.catalyst)}</p><div class="notice">这是本地纸面成交模拟，不向券商发送订单。下一步会展示金额、风险和集中度，请逐项复核。</div><form id="entry-form"><div class="form-grid"><label class="form-field">拟入场价<input class="input" name="entry" value="${s.entry}" readonly></label><label class="form-field">失效参考价<input class="input" name="invalidation" value="${s.invalidation}" readonly></label><label class="form-field">股数<input class="input" name="quantity" type="number" value="${s.max_shares}" min="1" step="1" required></label><label class="form-field">当前默认风险预算<input class="input" value="${money(s.risk_budget)}" readonly></label><label class="form-field full">持仓管理假设<textarea name="management_hypothesis" required maxlength="2000" placeholder="例如：仅在指引与价格结构保持有效时持有；逻辑失效后人工复核退出。"></textarea></label></div></form>`,`<button class="button ghost" data-action="close-modal">取消</button><button class="button primary" type="submit" form="entry-form">生成订单草稿 →</button>`);}
function intentModal(intent){modalData={intent,confirmKey:key()};const s=intent.sizing;openModal('2 / 2 · 确认纸面入场',`<p>请检查 ${esc(intent.ticker)} 的计划。这次确认将生成纸面成交和不可变 Thesis 快照。</p><dl class="key-values"><div><dt>股数 × 价格</dt><dd>${intent.quantity} × ${money(intent.entry)}</dd></div><div><dt>计划占用资金</dt><dd>${money(s.planned_capital)}</dd></div><div><dt>计划最大亏损</dt><dd>${money(s.planned_loss)}</dd></div><div><dt>失效价格</dt><dd>${money(intent.invalidation)}</dd></div><div><dt>入场后单票 / 板块占比</dt><dd>${pct(s.post_entry_exposure_pct.single_name)} / ${pct(s.post_entry_exposure_pct.sector)}</dd></div></dl><p>${esc(intent.management_hypothesis)}</p>${intent.warnings.length?`<div class="notice">${intent.warnings.map(x=>esc(reasons[x]||x)).join('<br>')}</div>`:''}<p class="label-note">此处为一次完整的用户确认。重复点击不会重复创建持仓。计划 5 分钟后过期；确认前再次复核风险。</p>`,`<button class="button ghost" data-action="cancel-intent">取消草稿</button><button class="button primary" data-action="confirm-intent">确认并记录纸面入场</button>`);}
function exitModal(pid,entry){modalData={positionId:pid,createKey:key()};openModal('1 / 2 · 记录纸面退出',`<form id="exit-form"><div class="form-grid"><label class="form-field">模拟退出价<input class="input" name="price" type="number" min="0.01" step="0.01" value="${esc(entry)}" required></label><label class="form-field">手续费<input class="input" name="fees" type="number" min="0" step="0.01" value="0" required></label><label class="form-field full">退出原因<textarea name="reason" required maxlength="2000" placeholder="记录触发退出的具体原因"></textarea></label></div><p>只有确认后才会关闭本地纸面持仓，系统不会发送实际卖出订单。</p></form>`,`<button class="button ghost" data-action="close-modal">取消</button><button class="button primary" type="submit" form="exit-form">预览退出 →</button>`);}
async function act(action,el){const id=el.dataset.id;switch(action){
case 'reload':return reload();
case 'refresh-all':for(const c of opportunities)await api('/opportunities/'+c.opportunity_id+'/refresh',{});await reload();toast('评估已刷新，证据和规则版本已保留');break;
case 'reset-filter':filterState=filterFamily=filterSearch='';render();break;
case 'watch':await api('/opportunities/'+id+'/watch',{});toast('已保留在观察列表');await reload();break;
case 'ignore':modalData={ignoreId:id};openModal('忽略此机会',`<p>忽略后会保留证据、计算与完整审计记录。历史记录仍可查看和导出。</p>`,`<button class="button ghost" data-action="close-modal">取消</button><button class="button primary" data-action="confirm-ignore">确认忽略</button>`);break;
case 'confirm-ignore':await api('/opportunities/'+modalData.ignoreId+'/ignore',{});$('#modal').close();await reload();toast('机会已忽略，历史记录已保留');break;
case 'replay':{const r=await api('/opportunities/'+id+'/replay');openModal('确定性重放验证',`<div class="notice ${r.match?'success':''}">${r.match?'通过：相同输入与规则版本产生相同核心输出。':'未通过：计算哈希不一致。'}</div><p class="hash">规则：${esc(r.rule_version)}<br>原始：${esc(r.expected_hash)}<br>重放：${esc(r.actual_hash)}</p>`,`<button class="button" data-action="close-modal">关闭</button>`);break;}
case 'enter':{const existing=(await api('/order-intents')).find(x=>x.opportunity_id===detail.opportunity_id&&x.status==='DRAFT');if(existing)intentModal(existing);else entryModal();break;}
case 'close-modal':$('#modal').close();break;
case 'confirm-intent':{await api('/order-intents/'+modalData.intent.intent_id+'/confirm',{confirmed:true},modalData.confirmKey);$('#modal').close();await reload();toast('纸面入场已记录，Thesis 与结果账本已创建');break;}
case 'cancel-intent':await api('/order-intents/'+modalData.intent.intent_id+'/cancel',{});$('#modal').close();toast('订单草稿已取消');break;
case 'exit':exitModal(id,el.dataset.entry);break;
case 'confirm-exit':await api('/exit-intents/'+modalData.exit.exit_intent_id+'/confirm',{confirmed:true},modalData.confirmKey);$('#modal').close();await reload();toast('纸面退出已记录，净损益已写入账本');break;
case 'sec-sync':toast('正在抓取 SEC 官方披露，可能需要几十秒…');{const r=await api('/sources/sec/sync',{security_id:id,limit:5});await reload();toast(`已归档 ${r.filings_archived} 份披露，等待事实复核`);}break;
case 'ibkr-sync':{const r=await api('/sources/ibkr/sync',{});await reload();toast(r.portfolio.reconciled?'账户快照已同步并通过对账':'快照已同步，待处理：'+r.portfolio.hard_blocks.join(' / '),!r.portfolio.reconciled);}break;
case 'integration-check':{const r=await api('/integrations/self-test',{});openModal('无账户集成自检',`<div class="notice ${r.passed?'success':''}">${r.passed?'通过':'未通过'} · 合成样例 · 外部网络请求 ${r.network_requests} 次</div><ul class="check-list">${r.checks.map(x=>`<li><span class="check-icon ${x.passed?'pass':''}">${x.passed?'✓':'×'}</span>${esc(x.name)}</li>`).join('')}</ul><dl class="key-values"><div><dt>事件 VWAP</dt><dd>${money(r.market.vwap)}</dd></div><div><dt>量比 / 板块超额收益</dt><dd>${r.market.reaction.relative_volume}× / ${pct(r.market.reaction.sector_excess_pct)}</dd></div><div><dt>风险限制后的最大股数</dt><dd>${r.risk.sizing.max_shares}</dd></div><div><dt>模拟成交 / 剩余</dt><dd>${r.partial_fill.filled_quantity} / ${r.partial_fill.remaining_quantity}</dd></div></dl><p>此结果只验证实现与计算，不代表真实账户或实时行情已连通。</p>`,`<button class="button" data-action="close-modal">关闭</button>`);break;}
case 'market-calculate':{const securities=await api('/securities');openModal('计算事件行情',`<form id="market-calculate-form"><label class="form-field">证券<select class="input" name="security_id">${securities.map(s=>`<option value="${esc(s.id)}">${esc(s.ticker)}</option>`).join('')}</select></label><label class="form-field">事件时间（含时区）<input class="input" name="event_at" placeholder="2026-09-25T08:00:00-04:00" required></label><p>自动拉取标的、SPY、板块 ETF、拆股与 20 个历史交易日同时间成交量，生成可审计快照。</p></form>`,`<button class="button primary" type="submit" form="market-calculate-form">拉取并计算</button>`);break;}
case 'broker-map':{const securities=await api('/securities');openModal('验证证券映射',`<form id="broker-map-form"><label class="form-field">证券<select class="input" name="security_id">${securities.map(s=>`<option value="${esc(s.id)}">${esc(s.ticker)}</option>`).join('')}</select></label><label class="form-field">IBKR conid<input class="input" type="number" min="1" step="1" name="conid" required></label><p>保存前会通过 Gateway 核验代码、股票类型和美元币种。</p></form>`,`<button class="button primary" type="submit" form="broker-map-form">核验并保存</button>`);break;}
case 'broker-plan':{const securities=await api('/securities');openModal('记录现有持仓风险计划',`<form id="broker-plan-form"><label class="form-field">证券<select class="input" name="security_id">${securities.map(s=>`<option value="${esc(s.id)}">${esc(s.ticker)}</option>`).join('')}</select></label><label class="form-field">失效参考价<input class="input" type="number" min="0.01" step="0.01" name="invalidation_price" required></label><label class="form-field">事件族<select class="input" name="event_family">${Object.keys(family).map(f=>`<option value="${esc(f)}">${esc(family[f])}</option>`).join('')}</select></label><p>保存后重新同步账户，才能纳入组合风险计算。</p></form>`,`<button class="button primary" type="submit" form="broker-plan-form">保存计划</button>`);break;}
case 'broker-orders':{const r=await api('/broker/orders');openModal('IBKR 券商订单与成交',r.items.length?`<pre class="hash">${esc(JSON.stringify(r.items,null,2))}</pre>`:'<p>尚无券商订单。该记录与本地演示成交隔离，接口默认关闭纸面提交。</p>',`<button class="button" data-action="close-modal">关闭</button>`);break;}
case 'research-run':await dashboardSync(true);break;
case 'sec-exhibits':{const r=await api('/research/exhibits',{filing_id:id});toast('已找到并归档 '+r.documents.length+' 份展品');}break;
case 'ai-extract':toast('DeepSeek 正在提取公开披露中的候选事实…');await api('/research/extract',{filing_id:id});location.hash='#research';await render();break;
case 'ai-explain':{toast('正在请求 DeepSeek 解释…');const r=await api('/opportunities/'+id+'/explain',{});openModal('DeepSeek 辅助解释',`<div class="notice">AI 生成，仅辅助阅读，不替代原文和规则。${r.cached?'复用相同输入的缓存结果。':''}</div><p>${esc(r.output.summary)}</p><h3>待注意事项</h3><ul>${r.output.risks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>待核实问题</h3><ul>${r.output.questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,`<button class="button" data-action="close-modal">关闭</button>`);break;}
case 'notice-read':await api('/research/notices/read',{id});await render();break;
case 'review-draft':{const data=await api('/research');const draft=data.drafts.find(x=>x.id===id);if(!draft)throw new Error('候选记录不存在');modalData={researchDraft:id};openModal('核对候选事实',`<div class="notice">请逐项核对数值、单位、期间、实际值/指引及 GAAP 口径。引用命中不代表语义正确。</div><div class="actions">${draft.documents.map(d=>`<a class="button" href="/api/v1/evidence/${esc(d.raw_document_id)}/raw" target="_blank" rel="noopener">${esc(d.form)} 原文 ${date(d.accepted_at)} ↗</a>`).join('')}</div><form id="research-approve-form"><label class="form-field spaced">候选事实 JSON（可修正）<textarea name="candidate" rows="16" required>${esc(JSON.stringify(draft.candidate,null,2))}</textarea></label><p><label><input type="checkbox" name="confirmed" required> 我已核对指标含义、单位、期间和原文</label></p></form>`,`<button class="button" data-action="close-modal">暂不确认</button><button class="button primary" type="submit" form="research-approve-form">验证并纳入研究</button>`);break;}
case 'market-sync':await api('/opportunities/'+id+'/market-sync',{});await reload();toast('行情快照与机会状态已重新计算');break;
case 'market-fetch':openModal('Massive 历史分钟行情',`<form id="market-form"><div class="form-grid"><label class="form-field full">交易代码<input class="input" name="symbol" placeholder="MSFT" required></label><label class="form-field">起始日期<input class="input" type="date" name="start" required></label><label class="form-field">结束日期<input class="input" type="date" name="end" required></label></div><p>需要在本机设置 MASSIVE_API_KEY。历史行情只归档，不自动生成实时入场条件。</p></form>`,`<button class="button" data-action="close-modal">取消</button><button class="button primary" type="submit" form="market-form">抓取并归档</button>`);break;
case 'import':{const file=$('#import-file').files[0];if(!file)throw new Error('请先选择 JSON 数据包');if(file.size>2*1024*1024)throw new Error('文件不得超过 2 MiB');const r=await api('/import',JSON.parse(await file.text()));toast('导入与验证完成');location.hash='#detail/'+r.opportunity_id;await loadData();await render();break;}
case 'audit':{const a=await api('/audit');openModal('追加式审计记录',`<div class="notice ${a.integrity.valid?'success':''}">哈希链${a.integrity.valid?'完整':'损坏'} · 共 ${a.integrity.count} 条记录</div><ol class="timeline">${a.items.slice(0,40).map(x=>`<li><strong>${esc(x.action)}</strong><small>${date(x.at)} · ${esc(x.entity_id)}</small><code class="hash">${esc(x.details_json)}</code></li>`).join('')}</ol>`,`<button class="button" data-action="close-modal">关闭</button>`);break;}
}}
document.addEventListener('click',async e=>{const ai=e.target.closest('[data-ai]');if(ai){try{await api('/settings',{ai_mode:ai.dataset.ai});await reload();toast('AI 模式已更新，核心决策未改变');}catch(err){toast(err.message,true);}return;}const tab=e.target.closest('[data-watch-tab]');if(tab){watchTab=tab.dataset.watchTab;render();return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const disabled=el.tagName==='BUTTON';if(disabled)el.disabled=true;try{await act(el.dataset.action,el);}catch(err){const target=$('#modal-error');if($('#modal').open&&target)target.textContent=err.message;else toast(err.message,true);}finally{if(disabled&&el.isConnected)el.disabled=false;}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['entry-form','exit-form','security-form','market-form','market-calculate-form','broker-map-form','broker-plan-form','research-preferences','research-approve-form'].includes(form.id))return;e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;const data=Object.fromEntries(new FormData(form));try{
if(form.id==='research-preferences'){const fd=new FormData(form);await api('/research/preferences',{families:fd.getAll('families'),security_ids:fd.getAll('security_ids'),watchlist_only:fd.has('watchlist_only'),auto_extract:fd.has('auto_extract')});toast('研究偏好已保存');await render();}
if(form.id==='research-approve-form'){const r=await api('/research/drafts/'+modalData.researchDraft+'/approve',{candidate:JSON.parse(data.candidate),confirmed:data.confirmed==='on'});$('#modal').close();await loadData();location.hash='#detail/'+r.opportunity_id;await render();}
if(form.id==='entry-form'){const intent=await api('/order-intents',{opportunity_id:modalData.opportunity.opportunity_id,quantity:Number(data.quantity),entry:Number(data.entry),invalidation:Number(data.invalidation),management_hypothesis:data.management_hypothesis},modalData.createKey);intentModal(intent);}
if(form.id==='exit-form'){const x=await api('/positions/'+modalData.positionId+'/exit-intent',{price:Number(data.price),fees:Number(data.fees),reason:data.reason},modalData.createKey);modalData={exit:x,confirmKey:key()};openModal('2 / 2 · 确认纸面退出',`<dl class="key-values"><div><dt>数量 / 退出价格</dt><dd>${x.quantity} / ${money(x.price)}</dd></div><div><dt>手续费</dt><dd>${money(x.fees)}</dd></div><div><dt>预估净损益</dt><dd>${money(x.estimated_net_pnl)}</dd></div></dl><p>${esc(x.reason)}</p>`,`<button class="button" data-action="close-modal">取消</button><button class="button primary" data-action="confirm-exit">确认记录退出</button>`);}
if(form.id==='security-form'){const ticker=data.ticker.toUpperCase();await api('/securities',{security:{security_id:'sec-'+data.cik+'-'+ticker.toLowerCase(),ticker,cik:data.cik,issuer_name:data.name,sector:data.sector,exchange:'US'}});await reload();toast('证券已注册，SEC 同步时将验证身份映射');}
if(form.id==='market-calculate-form'){const r=await api('/market/calculate',data);openModal('事件行情计算结果',`<div class="notice ${r.complete?'success':''}">${r.complete?'计算完成':'输入不完整'} · ${esc(r.data_mode)}</div><pre class="hash">${esc(JSON.stringify(r,null,2))}</pre>`,`<button class="button" data-action="close-modal">关闭</button>`);}
if(form.id==='broker-map-form'){await api('/broker/contracts/map',{...data,conid:Number(data.conid)});$('#modal').close();await reload();toast('证券映射已核验并保存');}
if(form.id==='broker-plan-form'){await api('/broker/position-plan',{...data,invalidation_price:Number(data.invalidation_price)});$('#modal').close();toast('计划已保存，请重新同步账户');}
if(form.id==='market-form'){const r=await api('/sources/massive/bars',{...data,symbol:data.symbol.toUpperCase()});openModal('历史行情已归档',`<div class="notice success">共 ${r.bars.length} 条分钟记录</div><p>${esc(r.note)}</p><p class="hash">SHA-256 ${esc(r.sha256)}</p>`,`<button class="button" data-action="close-modal">关闭</button>`);}
}catch(err){const target=$('#modal-error');if($('#modal').open&&target)target.textContent=err.message;else toast(err.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.id==='filter-state'){filterState=e.target.value;render();}if(e.target.id==='filter-family'){filterFamily=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='filter-search'){filterSearch=e.target.value;$('#filtered-table').innerHTML=table(filteredItems(opportunities));const download=$('#main .page-heading a[download]');if(download){const url=new URL(download.href);if(filterSearch)url.searchParams.set('q',filterSearch);else url.searchParams.delete('q');download.href=url.href;}}});
window.addEventListener('hashchange',render);
(async()=>{try{csrf=(await api('/session')).csrf_token;await reload();await dashboardSync();}catch(e){$('#main').innerHTML=`<div class="error-panel">连接失败：${esc(e.message)}。请确认本地服务仍在运行，然后刷新页面。</div>`;}})();


function showFreshness(data,error){
  let el=$('#freshness-banner');
  if(!el){el=document.createElement('div');el.id='freshness-banner';el.className='notice';el.setAttribute('role','status');$('#main').before(el);}
  const labels={UPDATING:'正在更新',NEVER_UPDATED:'尚未同步',DEGRADED:'更新不完整',STALE:'数据已过期',CURRENT:'本轮同步完成'};
  el.innerHTML=error?`连接中断：${esc(error)}。当前为缓存数据，不能视为最新。`:`<strong>${esc(labels[data.state]||data.state)}</strong> · ${esc(data.progress||'打开和返回页面时自动检查，每 15 分钟更新')}<br>最近完成同步：${date(data.last_run?.finished_at)}${data.last_run?.state&&data.last_run.state!=='SUCCEEDED'?'（尚未全部完成）':''} · ${data.market_configured?'行情按订阅权限提供，具体时点见机会详情':'未配置 Massive：行情与价格条件尚不可判断'}${data.auto_extract?'':' · 自动事实提取未开启'}${data.last_run?.errors?.length?`<br>${data.last_run.errors.map(esc).join('；')}`:''}<br><a href="#research">候选与待复核事实</a> · <a href="#settings">数据源设置</a>`;
}
async function dashboardSync(force=false){
  if(status.mode==='demo'||!csrf||syncBusy||document.hidden)return;
  syncBusy=true;
  try{
    const data=await api('/research/ensure',{force});
    if(data.last_run?.finished_at!==syncFinished){
      const editing=document.activeElement?.matches('input,textarea,select');
      if(!$('#modal').open && !editing){await reload();syncFinished=data.last_run?.finished_at;}
    }
    showFreshness(data);
  }catch(e){showFreshness(null,e.message);}
  finally{syncBusy=false;}
}
setInterval(()=>dashboardSync(),15000);
window.addEventListener('focus',()=>dashboardSync());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)dashboardSync();});

const impactStates={ASSESSED:'事实已复核',REVIEW_REQUIRED:'线索待复核',HISTORICAL:'观察期已结束',INVALIDATED:'判断已失效'};
function impactCard(c,compact=false){
  const links=c.evidence.filter(e=>e.raw_document_id).map(e=>e.raw_document_id);
  const inactive=['HISTORICAL','INVALIDATED'].includes(c.status);
  const basis=c.reasons.length?c.reasons[0].text:'缺少可靠的比较数据，暂不能判断涨跌。';
  const summary=`<div class="impact-title"><h3>${esc(c.ticker)} <span class="badge">${c.direction==='BULLISH'?'↗ ':c.direction==='BEARISH'?'↘ ':'◇ '}${esc(c.direction_label)}${!c.evidence_reviewed&&['BULLISH','BEARISH'].includes(c.direction)?'线索':''}</span></h3><span>${esc(impactStates[c.status]||c.status)}</span></div><small class="impact-date">披露 ${date(c.event_at)}</small><div class="impact-brief"><p class="impact-excerpt"><strong>${c.evidence_reviewed?'披露摘要':'披露摘要 · 待核对'}</strong><span>${esc(c.catalyst)}</span></p><p class="impact-excerpt"><strong>判断依据</strong><span>${esc(basis)}</span></p><p><strong>下一步</strong><span>${esc(c.next_step)}</span></p></div>`;
  if(compact)return `<article class="impact-card ${esc(c.direction.toLowerCase())}">${summary}<a class="text-link" href="#opportunities/impact-${encodeURIComponent(c.identity)}">深入研究 →</a></article>`;
  return `<article id="impact-${esc(c.identity)}" class="impact-card ${esc(c.direction.toLowerCase())} ${inactive?'inactive':''}">${summary}<details class="impact-depth"><summary>展开依据、行情与风险</summary><p><strong>完整披露摘要${c.evidence_reviewed?'':'（待核对）'}</strong><br>${esc(c.catalyst)}</p><small>判断计算：${date(c.as_of)}</small><dl class="impact-facts"><dt>为什么这样判断</dt><dd>${c.reasons.length?c.reasons.map(r=>esc(r.text)).join('<br>'):'缺少可靠的前后比较，无法推断方向。'}</dd><dt>现在还有机会吗</dt><dd>${esc(c.market.text)}${c.market.observed_return_pct!=null?`<br>事件后已发生涨跌：${pct(c.market.observed_return_pct)}；相对板块：${pct(c.market.observed_sector_excess_pct)}`:''}</dd><dt>观察期限</dt><dd>${c.horizons.map(h=>`${h.sessions} 个交易日：${h.state==='ELAPSED'?'已结束':h.state==='OPEN'?'观察中':'日历待补齐'}${h.ends_at?'（'+date(h.ends_at)+'）':''}`).join('<br>')}<br>这是验证窗口，不表示届时一定上涨或下跌。</dd><dt>可能涨跌多少</dt><dd>暂不估算：缺少经历史检验的概率与收益区间模型。</dd><dt>什么情况需要重新判断</dt><dd>${c.invalidation.map(esc).join('；')}</dd><dt>下一步</dt><dd><strong>${esc(c.next_step)}</strong></dd></dl><details><summary>判断限制与缺失条件（${c.limitations.length}）</summary><ul>${c.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}${c.conditions_missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="actions spaced">${[...new Set(links)].slice(0,3).map(id=>`<a class="button" href="/api/v1/evidence/${esc(id)}/raw" target="_blank" rel="noopener">核对原文 ↗</a>`).join('')}${c.identity.startsWith('draft:')?`<button class="button" data-action="review-draft" data-id="${esc(c.identity.slice(6))}">核对候选事实</button>`:`<a class="button" href="#detail/${esc(c.identity.slice(12))}">证据与计算</a>`}</div></details></article>`;
}
function researchPage(data,overview=false){
  const cards=data.impacts||[],active=cards.filter(c=>!['HISTORICAL','INVALIDATED'].includes(c.status)),positive=active.filter(c=>c.direction==='BULLISH'),negative=active.filter(c=>c.direction==='BEARISH'),unclear=active.filter(c=>!['BULLISH','BEARISH'].includes(c.direction)),past=cards.filter(c=>!active.includes(c));
  const group=(title,rows,message)=>section(title+(overview&&rows.length>3?'（展示最近 3 条 / 共 '+rows.length+' 条）':''),rows.length?`<div class="impact-grid">${(overview?rows.slice(0,3):rows).map(c=>impactCard(c,overview)).join('')}</div>`:empty(message,'请结合同步状态和待复核事实查看。'));
  return heading(overview?'DAILY OVERVIEW':'OPPORTUNITY RESEARCH',overview?'今日概览':'机会研究',overview?'先看方向、关键变化和下一步。':'先看结论，展开查看依据、行情和失效条件。',`<button class="button primary" data-action="research-run">更新判断与数据</button>`)+`<div class="impact-legend" aria-label="方向颜色说明"><span class="bullish">↗ 红色：偏多线索</span><span class="bearish">↘ 绿色：偏空线索</span><span class="mixed">◇ 黄色：多空分歧</span><span class="unknown">灰色：证据不足 / 已失效</span><small>方向用于研究筛选，不代表买入信号。</small></div><div class="stats-grid impact-stats">${stat('偏多线索',positive.length,'其中未复核线索不代表已确认机会','↗')}${stat('偏空线索',negative.length,'关注负面变化与持仓风险','↘')}${stat('分歧 / 证据不足',unclear.length,'明确保留判断的不确定性','◇')}${stat('历史 / 已失效',past.length,'观察期结束后归入复盘','◷')}</div>`+group('值得关注 · 偏多线索',positive,'暂无偏多线索')+group('下跌风险 · 偏空线索',negative,'暂无偏空线索')+group('暂不能判断 / 多空分歧',unclear,'暂无待判断事件') +(overview?section('研究待办',`<p>待复核事实：${data.drafts.filter(d=>d.status==='REVIEW_REQUIRED').length} · 未读提醒：${data.notices.filter(n=>!n.read_at).length}</p><div class="actions"><a class="button" href="#research">查看研究动态与核对原文 →</a><a class="button" href="#opportunities">查看全部判断（${cards.length}）→</a></div>`):`<details class="detail-panel"><summary>历史与已失效判断（${past.length}）</summary>${past.map(c=>impactCard(c)).join('')}</details><div class="actions spaced"><a class="button" href="#research">查看判断记录与复核事实 →</a></div>`);

}

function impactHistory(data){return section('最近判断记录',(data.impact_history||[]).length?`<p>自动更新完成时追加保存；记录时间不等于事件发生时间。尚未计算预测准确率。</p><div class="impact-history">${data.impact_history.map(h=>`<div><p>${date(h.recorded_at)} · ${esc(h.judgment.ticker)} · ${esc(h.judgment.direction_label)} · ${esc(impactStates[h.judgment.status])}</p><details><summary>查看当时依据</summary><p>${esc(h.judgment.catalyst)}</p><p>${h.judgment.reasons.map(r=>esc(r.text)).join('<br>')||'当时缺少可比较指标。'}</p><p>${h.judgment.limitations.map(esc).join('；')}</p><small>规则：${esc(h.judgment.rule_version)}</small></details></div>`).join('')}</div>`:empty('暂无已保存判断','首次更新完成后保存当前判断，未来追加变化，不覆盖旧版本。'));}
